const plans=[["전화 방식","라이트","19,900","이틀에 한 번 안부 · 하루 3분 통화",""],["전화 방식","스탠다드","24,900","주 5회 안부 · 하루 3분 통화",""],["전화 방식","플러스","29,900","매일 안부 · 하루 3분 통화",""],["앱 설치","무료 체험","무료","매일 안부 · 하루 5분 통화",""],["앱 설치","라이트","5,900","이틀에 한 번 안부 · 하루 3분 통화","4,900"],["앱 설치","스탠다드","8,900","매일 안부 · 하루 3분 통화","7,900"],["앱 설치","플러스","14,900","매일 안부 · 하루 5분 통화","13,900"]];const dialog=document.querySelector('#plan-dialog');document.querySelectorAll('[data-plan]').forEach(button=>button.addEventListener('click',()=>{const p=plans[Number(button.dataset.plan)];document.querySelector('#dialog-title').textContent=p[0]+' · '+p[1];document.querySelector('#dialog-price').textContent=p[2]==='무료'?'30일 무료 체험':'월 '+p[2]+'원 · 부가세 포함';document.querySelector('#dialog-call').textContent=p[3];dialog.showModal();}));dialog.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>dialog.close()));
